ga0L(){return"\u062a\u0639\u062f\u064a\u0644 \u0646\u0648\u0639 \u0627\u0644\u062d\u0627\u0644\u0629"},
ga0d(){return"\u0627\u0644\u0627\u0633\u0645"},
ga0g(){return"\u0639\u062f\u062f \u0627\u0644\u0623\u064a\u0627\u0645 \u0627\u0644\u0627\u0641\u062a\u0631\u0627\u0636\u064a \u062d\u062a\u0649 \u062a\u0627\u0631\u064a\u062e \u0627\u0644\u0627\u0633\u062a\u062d\u0642\u0627\u0642"},
