ga0l(){return"\u064a\u0633\u062a\u062e\u062f\u0645 \u062f\u0631\u062c\u0629 \u0627\u0644\u0644\u0648\u0646"},
ga0k(){return"\u0637\u0628\u0627\u0639\u0629 \u0642\u0627\u0626\u0645\u0629 \u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u062d\u0627\u0641\u0629/\u0627\u0644\u062a\u0645\u0627\u0633/\u0627\u0644\u0648\u0633\u064a\u0637 + \u0627\u0644\u0639\u0645\u0631/\u0627\u0644\u062c\u0646\u0633"},
ga0j(){return"\u0644\u0623\u0639\u0645\u0627\u0644 \u0627\u0644\u062a\u0627\u062c \u0648\u0627\u0644\u062c\u0633\u0631 \u2014 \u064a\u0636\u064a\u0641 \u0645\u0631\u0628\u0639\u0627\u062a \u0641\u0627\u0631\u063a\u0629 \u0644\u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u062d\u0627\u0641\u0629/\u0627\u0644\u062a\u0645\u0627\u0633/\u0627\u0644\u0648\u0633\u064a\u0637 \u0648\u0627\u0644\u0639\u0645\u0631/\u0627\u0644\u062c\u0646\u0633 \u0639\u0644\u0649 \u0627\u0644\u0645\u0644\u0635\u0642 \u0627\u0644\u0645\u0637\u0628\u0648\u0639 \u0644\u064a\u0636\u0639 \u0627\u0644\u0641\u0646\u064a \u0639\u0644\u0627\u0645\u0629 \u0639\u0644\u064a\u0647\u0627 \u064a\u062f\u0648\u064a\u064b\u0627. \u0623\u0648\u0642\u0641 \u0647\u0630\u0627 \u0627\u0644\u062e\u064a\u0627\u0631 \u0628\u0639\u062f \u0625\u0636\u0627\u0641\u0629 \u0646\u0641\u0633 \u0627\u0644\u062a\u0641\u0627\u0635\u064a\u0644 \u0643\u062e\u0635\u0627\u0626\u0635 \u062d\u0642\u064a\u0642\u064a\u0629 \u0644\u0646\u0648\u0639 \u0627\u0644\u062d\u0627\u0644\u0629 \u0647\u0630\u0627 (\u0644\u064a\u0639\u0631\u0636 \u0627\u0644\u0645\u0644\u0635\u0642 \u0627\u0644\u0642\u064a\u0645\u0629 \u0627\u0644\u0641\u0639\u0644\u064a\u0629 \u0628\u062f\u0644\u0627\u064b \u0645\u0646 \u0645\u0631\u0628\u0639 \u0641\u0627\u0631\u063a)."},
ga0i(){return"\u062f\u0648\u0627\u0626\u0631 \u0627\u0644\u062c\u0633\u0631 \u0639\u0644\u0649 \u0645\u062e\u0637\u0637 \u0627\u0644\u0623\u0633\u0646\u0627\u0646"},
ga0h(){return"\u0644\u0623\u0639\u0645\u0627\u0644 \u0627\u0644\u062a\u0627\u062c \u0648\u0627\u0644\u062c\u0633\u0631 \u0648\u0627\u0644\u0632\u0631\u0639\u0627\u062a: \u062f\u0627\u0626\u0631\u0629 \u0628\u064a\u0646 \u0633\u0646\u0651\u064a\u0646 \u0645\u062e\u062a\u0627\u0631\u064a\u0646 \u062a\u0631\u0628\u0637\u0647\u0645\u0627 \u0643\u062c\u0633\u0631\u060c \u0648\u064a\u064f\u0637\u0628\u0639 \u0627\u0644\u062c\u0633\u0631 \u0639\u0644\u0649 \u0627\u0644\u0645\u0644\u0635\u0642. \u0623\u0648\u0642\u0641\u0647 \u0644\u0644\u0623\u0646\u0648\u0627\u0639 \u0627\u0644\u062a\u064a \u0644\u0627 \u062a\u062d\u062a\u0648\u064a \u062c\u0633\u0648\u0631\u0627\u064b \u0623\u0628\u062f\u0627\u064b (\u0627\u0644\u0642\u0634\u0648\u0631\u060c \u0627\u0644\u0623\u0637\u0642\u0645\u060c \u0627\u0644\u0623\u062c\u0647\u0632\u0629)."},
ga1P(){return"\u0645\u0631\u062d\u0644\u0629 \u062a\u0641\u0631\u064a\u0642 \u0627\u0644\u062a\u0635\u0646\u064a\u0639"},
ga1O(){return"\u0639\u0646\u062f \u0645\u0633\u062d \u0637\u0644\u0628 \u0645\u062a\u0639\u062f\u062f \u0627\u0644\u0623\u0646\u0648\u0627\u0639 \u0644\u0644\u0627\u0646\u062a\u0642\u0627\u0644 \u0625\u0644\u0649 \u0647\u0630\u0647 \u0627\u0644\u0645\u0631\u062d\u0644\u0629 (\u0623\u0648 \u0645\u0646\u0647\u0627)\u060c \u062a\u0646\u062a\u0642\u0644 \u0641\u0642\u0637 \u0627\u0644\u0648\u062d\u062f\u0627\u062a \u0627\u0644\u062a\u064a \u062a\u0637\u0627\u0628\u0642 \u0645\u0627\u062f\u062a\u0647\u0627 \u0645\u0643\u064a\u0646\u0629 \u0627\u0644\u0641\u0646\u064a \u0627\u0644\u0630\u064a \u0645\u0633\u062d. \u0641\u0639\u0651\u0644 \u0647\u0630\u0627 \u0639\u0644\u0649 \u0645\u0631\u062d\u0644\u0629 \u0627\u0644\u0643\u0628\u0633/\u0627\u0644\u062e\u0631\u0627\u0637\u0629."},
ga15(){return"\u0645\u0633\u0627\u0631 \u0627\u0644\u062a\u0635\u0646\u064a\u0639"},
ga14(){return"\u0639\u0646\u062f \u0645\u0631\u062d\u0644\u0629 \u062a\u0641\u0631\u064a\u0642 \u0627\u0644\u062a\u0635\u0646\u064a\u0639\u060c \u0645\u0633\u062d \u0647\u0630\u0627 \u0627\u0644\u0641\u0646\u064a \u0641\u0642\u0637 \u064a\u0646\u0642\u0644 \u0627\u0644\u0648\u062d\u062f\u0627\u062a \u0627\u0644\u062a\u064a \u062a\u0633\u062a\u062e\u062f\u0645 \u0647\u0630\u0647 \u0627\u0644\u0645\u0627\u062f\u0629 \u0641\u064a \u0627\u0644\u0637\u0644\u0628 \u0627\u0644\u0645\u062a\u0639\u062f\u062f \u0627\u0644\u0623\u0646\u0648\u0627\u0639."},
ga16(){return"\u0628\u062f\u0648\u0646 \u0645\u0633\u0627\u0631 (\u064a\u0646\u062a\u0642\u0644 \u0645\u0639 \u0627\u0644\u0637\u0644\u0628)"},
ga0b(){return"\u064a\u062d\u0635\u0644 \u0646\u0648\u0639 \u0627\u0644\u062d\u0627\u0644\u0629 \u0627\u0644\u062c\u062f\u064a\u062f \u062a\u0644\u0642\u0627\u0626\u064a\u064b\u0627 \u0639\u0644\u0649 \u0645\u0631\u0627\u062d\u0644 \u0627\u0644\u0625\u0646\u062a\u0627\u062c \u0627\u0644\u0642\u064a\u0627\u0633\u064a\u0629 \u0627\u0644\u0633\u062a (\u0648\u0642\u0627\u0626\u0645\u0629 \u062f\u0631\u062c\u0627\u062a \u0627\u0644\u0644\u0648\u0646 \u0627\u0644\u0642\u064a\u0627\u0633\u064a\u0629 \u0627\u0644\u0645\u0643\u0648\u0651\u0646\u0629 \u0645\u0646 16 \u062f\u0631\u062c\u0629 \u0625\u0630\u0627 \u0643\u0627\u0646 \u064a\u0633\u062a\u062e\u062f\u0645 \u062f\u0631\u062c\u0629 \u0627\u0644\u0644\u0648\u0646) \u2014 \u0648\u0643\u0644\u0627\u0647\u0645\u0627 \u0642\u0627\u0628\u0644 \u0644\u0644\u062a\u0639\u062f\u064a\u0644 \u0644\u0627\u062d\u0642\u064b\u0627."},
ga0a(){return"\u0627\u0644\u0627\u062e\u062a\u0635\u0627\u0631 (\u0627\u062e\u062a\u064a\u0627\u0631\u064a)"},
ga09(){return"\u0645\u062b\u0627\u0644: CR"},
gHF(){return"\u063a\u064a\u0631 \u0645\u0641\u0639\u0651\u0644"},
ga0w(){return"\u0627\u0644\u0645\u062c\u0645\u0648\u0639\u0627\u062a \u0627\u0644\u0645\u062f\u0645\u062c\u0629"},
ga0v(){return"\u0623\u0646\u0645\u0627\u0637 \u062c\u0627\u0647\u0632\u0629 \u0644\u0623\u0646\u0648\u0627\u0639 \u062d\u0627\u0644\u0627\u062a \u062a\u064f\u0628\u0646\u0649 \u0645\u0639\u064b\u0627 \u062f\u0627\u0626\u0645\u064b\u0627 (\u0645\u062b\u0644 \u0627\u0644\u062f\u0639\u0627\u0645\u0629 \u0648\u0627\u0644\u062a\u0627\u062c) \u2014 \u0627\u062e\u062a\u0631\u0647\u0627 \u0641\u064a \u062d\u0627\u0644\u0629 \u062c\u062f\u064a\u062f\u0629 \u0644\u0625\u0646\u0634\u0627\u0621 \u0643\u0644 \u0646\u0648\u0639 \u062f\u0641\u0639\u0629 \u0648\u0627\u062d\u062f\u0629."},
ga02(){return"\u0627\u0644\u0633\u0645\u0627\u062d \u0628\u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631 \u0627\u0644\u062d\u0631"},
ga03(){return"\u0627\u0644\u0633\u0645\u0627\u062d \u0623\u064a\u0636\u064b\u0627 \u0644\u0634\u0627\u0634\u0629 \u062d\u0627\u0644\u0629 \u062c\u062f\u064a\u062f\u0629 \u0628\u0627\u062e\u062a\u064a\u0627\u0631 \u0623\u064a \u0645\u062c\u0645\u0648\u0639\u0629 \u0645\u0646 \u0623\u0646\u0648\u0627\u0639 \u0627\u0644\u062d\u0627\u0644\u0627\u062a \u0627\u0644\u0646\u0634\u0637\u0629 \u0645\u0628\u0627\u0634\u0631\u0629\u060c \u0643\u0644 \u0646\u0648\u0639 \u0645\u0639 \u0645\u0627\u062f\u062a\u0647/\u062f\u0631\u062c\u0629 \u0644\u0648\u0646\u0647 \u0627\u0644\u0627\u0641\u062a\u0631\u0627\u0636\u064a\u0629 \u0623\u062f\u0646\u0627\u0647 \u2014 \u0648\u0644\u064a\u0633 \u0641\u0642\u0637 \u0627\u0644\u0623\u0646\u0645\u0627\u0637 \u0627\u0644\u0645\u062d\u0641\u0648\u0638\u0629 \u0623\u0639\u0644\u0627\u0647."},
gHJ(){return"\u0627\u0644\u0627\u0641\u062a\u0631\u0627\u0636\u064a \u0644\u0647\u0630\u0627 \u0627\u0644\u0646\u0648\u0639 \u2014 \u064a\u064f\u0633\u062a\u062e\u062f\u0645 \u0623\u0648\u0644\u064b\u0627 \u0639\u0646\u062f \u0627\u062e\u062a\u064a\u0627\u0631 \u0647\u0630\u0627 \u0627\u0644\u0646\u0648\u0639 \u0641\u064a \u062d\u0627\u0644\u0629 \u062c\u062f\u064a\u062f\u0629"},
